args.command:
python - <<'PY'
from pathlib import Path
terms=('database-cleanup','database_cleanup','db-cleanup','db_cleanup','cron','nightly','cleanup')
for p in Path('.').rglob('*'):
    if not p.is_file() or any(x in p.parts for x in ('.git','node_modules')):
        continue
    try: s=p.read_text(errors='ignore')
    except OSError: continue
    hits=[(i+1,line) for i,line in enumerate(s.splitlines()) if any(t in line.lower() for t in terms)]
    if hits:
        print(p)
        for n,line in hits: print(f'{n}:{line}')
PY

